type TtsRequest struct {
    // TypeScript field: lexicon.
    // Existing pronunciation dictionary ID; selecting one uses WebSocket synthesis.
    // Pattern (ECMAScript): ^[\s\S]+$.
    Lexicon runtime.Optional[string]
    // TypeScript field: model.
    // Current production and preview aliases; both expose the same documented controls.
    // Default when omitted: "default". Omission is preserved by this type.
    Model runtime.Optional[TtsRequestModel]
    // TypeScript field: output.
    // Requested audio representation.
    Output TtsRequestOutput
    // TypeScript field: pacingBias.
    // Validation accepts -5–5; the recommended tuning range is -4–4.
    // Default when omitted: 0. Omission is preserved by this type.
    // Minimum: -5.
    // Maximum: 5.
    PacingBias runtime.Optional[float64]
    // TypeScript field: temperature.
    // Validation accepts 0–1.5; the recommended tuning range ends at 1.4.
    // Default when omitted: 0.7. Omission is preserved by this type.
    // Minimum: 0.
    // Maximum: 1.5.
    Temperature runtime.Optional[float64]
    // TypeScript field: text.
    // Text to synthesize, supplied whole or incrementally when the provider supports streaming input.
    Text TtsRequestText
    // TypeScript field: textNormalization.
    // Omission uses the selected voice's language rules.
    TextNormalization runtime.Optional[TtsRequestTextNormalization]
    // TypeScript field: timestampGranularity.
    // Native text segments, often but not always word-aligned.
    TimestampGranularity runtime.Optional[TtsRequestTimestampGranularity]
    // TypeScript field: voice.
    // Library or existing custom voice ID.
    // Pattern (ECMAScript): ^[\s\S]+$.
    Voice string
    // TypeScript field: voiceGuidance.
    // Validation accepts 1–10; the recommended tuning range is 1–4.
    // Default when omitted: 2. Omission is preserved by this type.
    // Minimum: 1.
    // Maximum: 10.
    VoiceGuidance runtime.Optional[float64]
}
